commands.command:
cat > /etc/nginx/sites-available/inventory-lb <<'EOF'
upstream inventory_backend {
    server 10.100.79.11:8080;
    server 10.100.79.12:8080;
}

server {
    listen 80 default_server;
    server_name _;

    location / {
        proxy_pass http://inventory_backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }
}
EOF
rm -f /etc/nginx/sites-enabled/default
ln -sf /etc/nginx/sites-available/inventory-lb /etc/nginx/sites-enabled/inventory-lb
nginx -t
